// simplified sketch of swapping a process out and back in
// not real kernel code

void swap_out(Process p) {
    write_entire_image_to_swap_area(p.memory_image);
    mark_all_frames_free(p.frames);
    p.state = SWAPPED_OUT;
}

void swap_in(Process p) {
    Frames frames = allocate_frames(p.memory_image.size);
    read_entire_image_from_swap_area(p.memory_image, frames);
    p.frames = frames;
    p.state = READY;
}

